# --------------------------------------------------------------------------
# Helpers (defined at file scope so BeforeAll can use them).
# --------------------------------------------------------------------------

function Initialize-ActWorkRepo {
    <#
        Copies the curated project files into a clean temp git repo, then writes
        the case's changed-files fixture and expected-labels assertion file.
    #>
    param(
        [Parameter(Mandatory)] [string]   $Source,
        [Parameter(Mandatory)] [string]   $Dest,
        [Parameter(Mandatory)] [string[]] $ChangedFiles,
        [Parameter(Mandatory)] [AllowEmptyCollection()] [string[]] $ExpectedLabels
    )

    foreach ($item in @('PRLabelAssigner.psm1', 'Invoke-PRLabelAssigner.ps1', 'labeler-rules.json', '.actrc', '.github', 'tests')) {
        $src = Join-Path $Source $item
        if (Test-Path -LiteralPath $src) {
            Copy-Item -LiteralPath $src -Destination $Dest -Recurse -Force
        }
    }

    # Write the per-case fixtures fresh (do NOT copy the repo's sample fixtures).
    $fixtureDir = Join-Path $Dest 'fixtures'
    New-Item -ItemType Directory -Path $fixtureDir -Force | Out-Null
    Set-Content -LiteralPath (Join-Path $fixtureDir 'changed-files.txt') -Value ($ChangedFiles -join "`n") -Encoding utf8

    if ($ExpectedLabels.Count -eq 0) {
        # A comment-only file still triggers the in-workflow assertion, which
        # then confirms the EMPTY result is correct.
        Set-Content -LiteralPath (Join-Path $fixtureDir 'expected-labels.txt') -Value "# no labels expected" -Encoding utf8
    }
    else {
        Set-Content -LiteralPath (Join-Path $fixtureDir 'expected-labels.txt') -Value ($ExpectedLabels -join "`n") -Encoding utf8
    }

    Push-Location $Dest
    try {
        git init -q 2>&1 | Out-Null
        git config user.email 'harness@example.com' 2>&1 | Out-Null
        git config user.name  'PR Label Harness'    2>&1 | Out-Null
        git config commit.gpgsign false             2>&1 | Out-Null
        git checkout -q -b main 2>&1 | Out-Null
        git add -A 2>&1 | Out-Null
        git commit -q -m 'fixture commit' 2>&1 | Out-Null
    }
    finally {
        Pop-Location
    }
}

function Invoke-ActPush {
    param([Parameter(Mandatory)] [string] $WorkDir)
    Push-Location $WorkDir
    try {
        # Capture stdout+stderr together; rely on the copied .actrc to map
        # ubuntu-latest -> the pwsh-enabled image.
        $output = & act push --rm --container-architecture linux/amd64 2>&1
        return [pscustomobject]@{
            ExitCode = $LASTEXITCODE
            Lines    = @($output | ForEach-Object { [string]$_ })
        }
    }
    finally {
        Pop-Location
    }
}

function Get-FramedLabel {
    <#
        Extracts the ordered label set from the LABELS_BEGIN/LABELS_END frame in
        act's output. act prefixes each workflow log line with a job banner and
        '| ', and may inject ANSI colour codes — both are stripped first.
    #>
    param([Parameter(Mandatory)] [AllowEmptyCollection()] [string[]] $Lines)

    $labels  = [System.Collections.Generic.List[string]]::new()
    $inFrame = $false
    foreach ($raw in $Lines) {
        $clean = $raw -replace "`e\[[0-9;]*m", ''     # ESC-style ANSI
        $clean = $clean -replace '\x1b\[[0-9;]*m', '' # belt-and-suspenders
        $clean = $clean -replace '^.*?\|\s?', ''      # drop act's '[Job]  | ' prefix
        $clean = $clean.Trim()
        if     ($clean -ceq 'LABELS_END')   { $inFrame = $false; continue }
        elseif ($inFrame)                   { if ($clean) { $labels.Add($clean) } }
        elseif ($clean -ceq 'LABELS_BEGIN') { $inFrame = $true }
    }
    return , $labels.ToArray()
}

# --------------------------------------------------------------------------
# Test cases — each lists the simulated changed files and the EXACT expected
# labels (in priority order). The expectations match the rules in
# labeler-rules.json and were verified against the script before running act.
# --------------------------------------------------------------------------
BeforeDiscovery {
    $script:Cases = @(
        @{
            Name           = 'docs-only'
            ChangedFiles   = @('docs/intro.md', 'docs/guide/setup.md')
            ExpectedLabels = @('documentation')
        },
        @{
            # api/backend (50) -> tests (40) -> documentation (10); the 'area'
            # group resolves to area/api (9), beating area/core (5): conflict
            # resolution. README.md contributes 'documentation' via **/*.md.
            Name           = 'api-tests-and-group-conflict'
            ChangedFiles   = @('src/api/users.ps1', 'src/api/users.test.ps1', 'README.md')
            ExpectedLabels = @('api', 'backend', 'tests', 'documentation', 'area/api')
        },
        @{
            Name           = 'no-match'
            ChangedFiles   = @('LICENSE', '.gitignore')
            ExpectedLabels = @()
        }
    )
}

BeforeAll {
    $script:RepoRoot   = Split-Path $PSScriptRoot -Parent
    $script:ResultFile = Join-Path $RepoRoot 'act-result.txt'

    foreach ($tool in 'act', 'docker', 'git') {
        if (-not (Get-Command $tool -ErrorAction SilentlyContinue)) {
            throw "Required tool '$tool' not found on PATH."
        }
    }

    # Start a fresh result log.
    "PR Label Assigner - act results" | Set-Content -LiteralPath $ResultFile -Encoding utf8

    # Run every case through act exactly once and cache the parsed results so
    # the It blocks below only assert (no extra act runs).
    $script:Results = @{}
    foreach ($case in $script:Cases) {
        $tmp = Join-Path ([System.IO.Path]::GetTempPath()) ("pr-label-act-" + [guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $tmp -Force | Out-Null
        try {
            Initialize-ActWorkRepo -Source $RepoRoot -Dest $tmp `
                -ChangedFiles   $case.ChangedFiles `
                -ExpectedLabels $case.ExpectedLabels

            $run = Invoke-ActPush -WorkDir $tmp

            $expectedDisplay = if ($case.ExpectedLabels.Count -eq 0) { '<none>' } else { $case.ExpectedLabels -join ', ' }
            $header = @"

================================================================================
Test case      : $($case.Name)
ChangedFiles   : $($case.ChangedFiles -join ', ')
ExpectedLabels : $expectedDisplay
act exit code  : $($run.ExitCode)
================================================================================
"@
            Add-Content -LiteralPath $ResultFile -Value $header -Encoding utf8
            Add-Content -LiteralPath $ResultFile -Value ($run.Lines -join "`n") -Encoding utf8

            $script:Results[$case.Name] = [pscustomobject]@{
                ExitCode      = $run.ExitCode
                Labels        = @(Get-FramedLabel -Lines $run.Lines)
                JobsSucceeded = @($run.Lines | Where-Object { $_ -match 'Job succeeded' }).Count
                SawAssertion  = @($run.Lines | Where-Object { $_ -match 'ASSERTION_PASSED' }).Count -ge 1
            }
        }
        finally {
            Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
        }
    }
}

Describe 'PR Label Assigner end-to-end via act' {

    It 'produced act-result.txt' {
        Test-Path -LiteralPath $script:ResultFile | Should -BeTrue
    }

    Context 'case <Name>' -ForEach $script:Cases {

        BeforeAll {
            $script:Result = $script:Results[$Name]
        }

        It 'act exited with code 0' {
            $script:Result.ExitCode | Should -Be 0
        }

        It 'both jobs reported "Job succeeded"' {
            $script:Result.JobsSucceeded | Should -BeGreaterOrEqual 2
        }

        It 'the in-workflow assertion fired (ASSERTION_PASSED)' {
            $script:Result.SawAssertion | Should -BeTrue
        }

        It 'emitted exactly the expected labels, in order' {
            ($script:Result.Labels -join '|') | Should -BeExactly ($ExpectedLabels -join '|')
        }
    }
}

