            $script:Results[$Name].SawAssertion | Should -BeTrue
        }

        It 'emitted exactly the expected labels, in order' {
            $r = $script:Results[$Name]
            ($r.Labels -join '|') | Should -BeExactly ($r.ExpectedLabels -join '|')
        }
    }
}
